--query to calculate the total revenue generated by each product
SELECT*FROM OrderDetails$ 

SELECT ProductID, SUM(TotalPrice) AS TotalRevenue
FROM OrderDetails$ 
GROUP BY ProductID
ORDER BY TotalRevenue  

--query to find the average total order amount per customer
SELECT*FROM Orders$ 
SELECT* FROM Customers 

SELECT CustomerID, AVG(TotalAmount) AS AverageTotalAmount
FROM Orders$ 
GROUP BY CustomerID
ORDER BY AverageTotalAmount DESC

SELECT c.CustomerID, c.FirstName, c.LastName, c.Email,c. City, AVG (o.TotalAmount) AS AverageTotalOrderAmount
FROM Customers c
FULL OUTER JOIN Orders$ o on c.CustomerID = o.CustomerID
GROUP BY  c.CustomerID, c.FirstName, c.LastName, c.Email,c. City
ORDER BY c.CustomerID 


--Query to calculate the total quantity sold for each product category
SELECT * FROM OrderDetails$ ORDER BY ProductID 
SELECT *FROM Products ORDER BY ProductID 

SELECT  p.Category, SUM(p.StockQuantity) AS TotalStockQuantity, SUM(o.Quantity) AS TotalQuantitySold 
FROM Products p
FULL OUTER JOIN OrderDetails$ o  on p.ProductID = o.ProductID 
GROUP BY p.Category  
ORDER BY TotalQuantitySold 


/*Query to find the top 5 most expensive orders based on the 
TotalAmount from the Orders table*/
SELECT TOP 5 * FROM Orders$ 
ORDER BY TotalAmount DESC


--Query to calculate the total revenue generated per month
SELECT * FROM Orders$ ORDER BY OrderID
SELECT * FROM OrderDetails$ ORDER BY OrderID

SELECT  YEAR(r.OrderDate) AS OrderYear, DATENAME (month, r.OrderDate) AS OrderMonth, SUM(o.TotalPrice) AS TotalRevenue
FROM OrderDetails$ o
FULL OUTER JOIN Orders$ r on o.OrderID = r.OrderID 
GROUP BY  YEAR(r.OrderDate), DATENAME (month, r.OrderDate)    
ORDER BY YEAR(r.OrderDate), DATENAME (month, r.OrderDate)  

/*Query to get a summary of each customer’s orders, including their
full name, total number of orders, and total amount spent*/
SELECT*FROM Customers
SELECT*FROM Orders$ ORDER BY OrderID
SELECT*FROM OrderDetails$ ORDER BY OrderID

SELECT o.CustomerID, CONCAT(c.FirstName,' ',c.LastName) AS FullName, COUNT (DISTINCT od.OrderID) AS TotalOrders, SUM(o.TotalAmount) AS TotalAmountSpent
FROM Orders$ o
INNER JOIN Customers c ON c.CustomerID = o.CustomerID
INNER JOIN OrderDetails$ od ON o.OrderID = od.OrderID 
GROUP BY o.CustomerID, c.FirstName, c.LastName 
ORDER BY CustomerID


--Write a query to find the total revenue and remaining stock for each product

SELECT*FROM Products 
SELECT*FROM OrderDetails$ 

SELECT p.ProductID, SUM(od.TotalPrice) AS TotalRevenue, SUM(p.StockQuantity) AS StockQuantities, (SUM(p.StockQuantity) - COALESCE (SUM(od.Quantity),0)) AS RemainingStock
FROM Products p
FULL OUTER JOIN OrderDetails$ od ON p.ProductID=od.ProductID
GROUP BY p.ProductID  
ORDER BY p.ProductID
